create temporary view dwd_data_order_${grass_region_without_quote} as
select
    price_usd
    ,a.item_id
    ,COALESCE(order_price_usd, 0) AS order_price_usd
    ,coalesce(cast(is_ads as string), 'false') as is_ads
    ,array_intersect( array_union(array_union(COALESCE(split(algo_tag,','),array()), COALESCE(split(source1_algo_tag,','),array())), COALESCE(split(source2_algo_tag,','),array())),
        array('DA_Daily Discover','DA_You May Also Like','DA_Cart_Unify')) AS scenario_tags
    ,exp_group_ids
    ,COUNT(1) AS operation_cnt
from
    srdi_mart.dwd_sr_data_warehouse_platform a 
    INNER JOIN dim_item_price_${grass_region_without_quote} b 
        ON a.item_id = b.item_id
    LEFT JOIN dim_item_order_price_${grass_region_without_quote} c 
        ON a.item_id = c.item_id
        AND a.order_id = c.order_id
where
    grass_region in (${grass_region})
    and operation in ('order')
    and local_date = ${local_date}
    and size(exp_group_ids) > 0
    and a.item_id > 0
    and (
        size(array_intersect(split(algo_tag, ','),
            array('DA_Daily Discover','DA_You May Also Like','DA_Cart_Unify')
        )) > 0 OR size(array_intersect(split(source1_algo_tag, ','),
            array('DA_Daily Discover','DA_You May Also Like','DA_Cart_Unify')
        )) > 0 OR size(array_intersect(split(source2_algo_tag, ','),
            array('DA_Daily Discover','DA_You May Also Like','DA_Cart_Unify')
        )) > 0
    )
    and operation_cnt > 0
GROUP BY 
    1,2,3,4,5,6;

