create temporary view sr_features_inter_${grass_region_without_quote} as
select
    a.exp_group_id
    ,coalesce(cast(is_ads as string), 'false') as is_ads
    ,case when scenario_tag = '__ALL__' then 'all'
        when scenario_tag = 'DA_Cart_Unify' then 'Cart Unify'
        else replace(scenario_tag, 'DA_', '') end as feature_group
    ,a.item_id
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(ppv_cnt_exclude_isback) AS ppv_cnt_exclude_isback
    ,SUM(cart_cnt) AS cart_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
from
    srdi_mart.dws_sr_data_warehouse_platform_item_exp_level_benchmark_1d a 
    inner join dim_exp_group_filter_${grass_region_without_quote} as b
        on a.exp_group_id = b.exp_group_id
    INNER JOIN dim_item_price_${grass_region_without_quote} c
        ON a.item_id = c.item_id
where
    exp_type = 'traffic'
    and grass_region in (${grass_region})
    and local_date = ${local_date}
    and a.item_id > 0
    and feature_detail = '__ALL__'
    and scenario_tag in ('DA_You May Also Like', 'DA_Cart_Unify', 'DA_Daily Discover')
GROUP BY 
    1,2,3,4;

