    ,sum(coalesce(click_cnt, 0)) as click_cnt
    ,sum(coalesce(ppv_cnt_exclude_isback, 0)) as ppv_cnt
    ,sum(coalesce(cart_cnt, 0)) as cart_cnt
    ,sum(coalesce(order_cnt, 0)) as order_cnt
    ,sum(coalesce(gmv, 0)) as gmv
