create temporary view ads_features_raw_${grass_region_without_quote} as
select
    case
        when entrance in (8, 9, 10, 11, 40) then 'Cart Unify'
        when entrance = 4 then 'You May Also Like'
        when entrance in (3, 25, 31, 32) then 'Daily Discover'
    end as feature_group
    ,user_id
    ,item_id
    ,SUM(broad_gmv_usd) AS broad_gmv_usd
    ,SUM(revenue_usd) AS revenue_usd
    ,SUM(ads_gmv_usd) AS ads_gmv_usd
from
    srdi_mart.dws_sr_data_warehouse_ads_request_benchmark_advv_1d
where
    grass_region in (${grass_region})
    and local_date = ${local_date}
    and entrance in (8, 9, 10, 11, 3, 25, 31, 32, 4, 40)
    and (broad_gmv_usd > 0 or revenue_usd > 0 or ads_gmv_usd > 0)
    and user_id > 0
GROUP BY 
    1,2,3;

