create temporary view agg_order_price_${grass_region_without_quote} as
select
    a.exp_group_id
    ,IF(is_ads IS NULL, '__ALL__', is_ads) AS is_ads
    ,case when scenario_tag = '__ALL__' then 'all'
        when scenario_tag = 'DA_Cart_Unify' then 'Cart Unify'
        else replace(scenario_tag, 'DA_', '') end as feature_group
    ,item_id
    ,SUM(order_price_usd * operation_cnt) / SUM(operation_cnt) AS order_price_usd
from
    dws_data_order_explode_${grass_region_without_quote} a
