create temporary view joined_features_${grass_region_without_quote} as
select
    a.exp_group_id
    ,a.is_ads
    ,a.feature_group
    ,a.item_id
    ,imp_cnt
    ,click_cnt
    ,ppv_cnt
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,pc2_gmv
    ,revenue_usd
    ,broad_gmv_amt_usd
    ,ads_order_gmv_usd
    ,price_usd
    ,order_price_usd
from
    sr_features_${grass_region_without_quote} as a
    INNER JOIN dim_item_price_${grass_region_without_quote} b
        ON a.item_id = b.item_id
left join
    agg_order_price_${grass_region_without_quote} as c
on
    a.exp_group_id = c.exp_group_id
    and a.is_ads = c.is_ads
    and a.feature_group = c.feature_group
    and a.item_id = c.item_id

left join
    ads_features_inter_${grass_region_without_quote} as d
on
    a.exp_group_id = d.exp_group_id
    and a.feature_group = d.feature_group
    and a.item_id = d.item_id
;

