create temporary view price_pct_with_features_${grass_region_without_quote} as
select
/*+ BROADCAST(a) */
    a.exp_group_id
    ,a.is_ads
    ,a.feature_group
    ,operation
    ,percentile

    ,count(distinct item_id) as item_cnt
    ,sum(imp_cnt) as imp_cnt
    ,sum(click_cnt) as click_cnt
    ,sum(ppv_cnt) as ppv_cnt
    ,sum(cart_cnt) as cart_cnt
    ,sum(order_cnt) as order_cnt
    ,sum(gmv) as gmv
    ,sum(pc2_gmv) as pc2_gmv
    ,sum(coalesce(revenue_usd, 0)) as revenue_usd
    ,sum(coalesce(ads_order_gmv_usd, 0)) as ads_order_gmv_usd
    ,sum(coalesce(broad_gmv_amt_usd, 0)) as broad_gmv_usd
from
    price_pct_explode_${grass_region_without_quote} as a
inner join
    joined_features_${grass_region_without_quote} as b
on
    a.exp_group_id = b.exp_group_id
    and a.is_ads = b.is_ads
    and a.feature_group = b.feature_group
    and (
        (operation = 'order_paid'
        and order_cnt > 0
        and order_price_usd <= price
        )
        or
        (operation <> 'order_paid'
        and (
            case
                when operation='impression' then imp_cnt > 0
                when operation='click' then click_cnt > 0
                when operation='order' then order_cnt > 0
                else false end
            )
        and price_usd <= price
        )
    )
group by
    a.exp_group_id
    ,a.is_ads
    ,a.feature_group
    ,operation
    ,percentile
;

