insert overwrite table ${schema}.dws_sr_data_warehouse_rcmd_exp_scenario_level_price_percentile_1d
partition (local_date = ${local_date}, grass_region = ${grass_region})
select
/*+ REPARTITION(8) */
    a.exp_group_id
    ,a.is_ads
    ,a.feature_group
    ,a.operation
    ,a.percentile
    ,price as price_thres
    ,avg_price
    ,coalesce(item_cnt, 0) as item_cnt
    ,coalesce(imp_cnt, 0) as imp_cnt
    ,coalesce(click_cnt, 0) as click_cnt
    ,coalesce(ppv_cnt, 0) as ppv_cnt
    ,coalesce(cart_cnt, 0) as cart_cnt
    ,coalesce(order_cnt, 0) as order_cnt
    ,coalesce(gmv, 0) as gmv
    ,coalesce(pc2_gmv, 0) as pc2_gmv
    ,coalesce(revenue_usd, 0) as revenue_usd
    ,coalesce(ads_order_gmv_usd, 0) as ads_order_gmv_usd
    ,coalesce(broad_gmv_usd, 0) as broad_gmv_usd
from
    price_pct_explode_${grass_region_without_quote} as a
left join
    price_pct_with_features_${grass_region_without_quote} as b
on
    a.exp_group_id = b.exp_group_id
    and a.is_ads = b.is_ads
    and a.feature_group = b.feature_group
    and a.operation = b.operation
    and a.percentile = b.percentile
;
